package com.example.starter.domain;

/**
 * 引航计划状态机：申请 → 编排 → 确认 → 执行 → 核销；执行前可取消。
 */
public enum PlanStatus {
    /** 已申请，尚未编排引航员/拖轮/潮水窗口。 */
    APPLIED,
    /** 已编排：绑定引航员、拖轮组合与潮水窗口，尚未锁定。 */
    SCHEDULED,
    /** 已确认：引航员与拖轮已在同一事务内锁定。 */
    CONFIRMED,
    /** 执行中。 */
    EXECUTING,
    /** 已核销（终态）。 */
    SETTLED,
    /** 已取消（终态）。 */
    CANCELLED
}

package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时钟配置：业务时间统一走 Clock，便于测试注入可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 系统默认时钟（Asia/Shanghai 由序列化层处理，业务比较使用 Instant/LocalDateTime）。
     */
    @Bean
    public Clock businessClock() {
        return Clock.systemDefaultZone();
    }
}

package com.example.starter.web;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码，由全局异常处理器转换为错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, message);
    }
}

package com.example.starter.web;

import java.util.Map;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 全局异常处理：业务异常按状态码返回，参数校验失败返回 400。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.status())
                .body(Map.of("error", ex.getMessage(), "status", ex.status().value()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .map(e -> e.getField() + " " + e.getDefaultMessage())
                .findFirst()
                .orElse("参数校验失败");
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(Map.of("error", message, "status", 400));
    }
}

